// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// Robust: wrap external .all() in try/catch to handle parallel branch failures
let articles = [], courses = [];
try {
  articles = $('Airtable — Articles récents').all().map(i => i.json)
    .filter(a => a.Status === 'produit_draft' || a.Status === 'publié').slice(-5);
} catch(e) { articles = []; }
try {
  courses = $('Airtable — Cours récents').all().map(i => i.json)
    .filter(c => c.Status !== 'nouveau').slice(-3);
} catch(e) { courses = []; }
return [{ json: { recent_articles: articles, recent_courses: courses } }];

const response = $input.first().json;

let newsletter;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  newsletter = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing newsletter: ' + e.message);
}

return [{
  json: {
    subject: newsletter.subject || 'Newsletter Max-Morrys',
    preview_text: newsletter.preview_text || '',
    html_body: newsletter.html_body || '',
    plain_text: newsletter.plain_text || '',
    main_cta: newsletter.main_cta || {},
    generated_at: new Date().toISOString(),
    status: 'draft'
  }
}];

